<section class="health-workspace"><?php
$workerPath='C:/xampp/cybersecurity-private/mail-health.json';$worker=is_file($workerPath)?json_decode(file_get_contents($workerPath),true):[];
$heartbeat=$worker['finished_at']??null;$workerFresh=$heartbeat&&time()-strtotime($heartbeat)<180;
$workerStatus=empty(gmail_config()['enabled'])?'Disabled':(!$heartbeat?'Never ran':(!$workerFresh?'Stale':(($worker['status']??'')==='error'?'Failed':'Running on schedule')));
$oldestPending=$db->query("SELECT MIN(created_at) FROM (SELECT created_at FROM mail_deliveries WHERE status IN ('pending','retry') UNION ALL SELECT created_at FROM account_mail WHERE status IN ('pending','retry')) queued_mail")->fetchColumn()?:'None';
$collectorPath='C:/xampp/cybersecurity-private/collector-error.json';$collectorError=is_file($collectorPath)?json_decode(file_get_contents($collectorPath),true):[];
$started=microtime(true);$db->query('SELECT 1')->fetchColumn();$probe=round((microtime(true)-$started)*1000,2);
$today=(int)$db->query('SELECT COUNT(*) FROM security_events WHERE received_at>=CURDATE()')->fetchColumn();
$lag=$db->query('SELECT ROUND(AVG(GREATEST(0,TIMESTAMPDIFF(SECOND,occurred_at,received_at))),2) FROM security_events WHERE received_at>=NOW()-INTERVAL 24 HOUR')->fetchColumn();
$hourly=array_fill(0,24,['count'=>0,'lag'=>0]);foreach($db->query('SELECT HOUR(received_at) hour,COUNT(*) n,AVG(GREATEST(0,TIMESTAMPDIFF(SECOND,occurred_at,received_at))) delay FROM security_events WHERE received_at>=CURDATE() GROUP BY hour') as $r)$hourly[(int)$r['hour']]=['count'=>(int)$r['n'],'lag'=>round((float)$r['delay'],2)];
?>
<div class="collection-hero panel"><div><span class="eyebrow">COLLECTION HEALTH</span><h2>Student portal monitoring</h2><p>Server-side collection and synchronous rule evaluation</p></div><span class="state-tag">Database reachable</span></div><div class="health-measures"><?php foreach(['Events received today'=>$today,'Database probe'=>$probe.' ms','Average receipt delay / 24h'=>$lag!==null?$lag.' sec':'No observations','Last received event'=>$latest] as $label=>$value):?><article class="panel"><span><?=h($label)?></span><strong><?=h($value)?></strong></article><?php endforeach;?></div>
<div class="health-grid"><article class="panel module-panel"><div class="panel-heading"><div><h2>Collection volume</h2><p>Events successfully stored each hour today / PHT</p></div><span class="soft-badge">24 hours</span></div><div class="health-bars"><?php $peak=max(1,max(array_column($hourly,'count')));foreach($hourly as $hour=>$r):?><div class="health-bar-column"><div tabindex="0" title="<?=h(sprintf('%02d:00',$hour).' / '.$r['count'].' events')?>" style="height:<?=max(2,140*$r['count']/$peak)?>px"><span class="chart-tooltip"><?=h(sprintf('%02d:00',$hour).' / '.$r['count'].' events')?></span></div><small><?=$hour%3===0?sprintf('%02d',$hour):''?></small></div><?php endforeach;?></div><p class="chart-caption">Zero counts can mean no activity; they do not establish a collector outage.</p></article><article class="panel module-panel"><div class="panel-heading"><div><h2>Receipt delay trend</h2><p>Hourly average / seconds from event to database receipt</p></div></div><?php $peak=max(1,max(array_column($hourly,'lag')));$points=[];foreach($hourly as $hour=>$r)if($r['count'])$points[]=(12+$hour*20).','.round(140-110*$r['lag']/$peak);?><svg class="health-delay" viewBox="0 0 484 160" role="img" aria-label="Recorded receipt delay, zero to <?=h($peak)?> seconds"><path d="M12 30H472 M12 85H472 M12 140H472" fill="none" stroke="#35414d"/><polyline points="<?=implode(' ',$points)?>" fill="none" stroke="#54d6a0" stroke-width="3"/><?php foreach($hourly as $hour=>$r):if(!$r['count'])continue;?><circle cx="<?=12+$hour*20?>" cy="<?=round(140-110*$r['lag']/$peak)?>" r="4" fill="#54d6a0"><title><?=h(sprintf('%02d:00',$hour).' / '.$r['lag'].' seconds')?></title></circle><?php endforeach;?></svg><div class="delay-axis"><span>00:00</span><span>12:00</span><span>23:00</span></div><p class="chart-caption">Scale: 0–<?=h($peak)?> seconds. Timestamps have one-second precision. Missing hours have no samples; this is not full request-processing latency.</p></article></div>
<div class="service-grid"><?php foreach([['Database','Connected','Probe: '.$probe.' ms'],['Event collector','On request','Latest event: '.$latest],['Rule evaluation','Synchronous','Runs within event collection'],['Gmail delivery',$workerStatus,'Last run: '.($heartbeat?:'None')]] as $service):?><article class="panel service-card"><div><span class="status-dot <?=$service[1]==='Not configured'?'offline':''?>"></span><h2><?=h($service[0])?></h2></div><span class="state-tag"><?=h($service[1])?></span><small><?=h($service[2])?></small></article><?php endforeach;?></div>
<?php
$activityTotal=(int)$db->query('SELECT COUNT(*) FROM security_events')->fetchColumn();
$activityPages=max(1,(int)ceil($activityTotal/10));
$activityPage=min(max(1,(int)filter_input(INPUT_GET,'activity_page',FILTER_VALIDATE_INT)),$activityPages);
$activityOffset=($activityPage-1)*10;
?><div id="collection-activity"><?php panel_start('Recent collection activity','Successful database writes / 10 records per page');live_table(['ID','RECEIVED (PHT)','EVENT','IP ADDRESS'],$db->query('SELECT id,received_at,event_type,source_ip FROM security_events ORDER BY id DESC LIMIT 10 OFFSET '.$activityOffset)->fetchAll(PDO::FETCH_NUM));?>
<nav class="record-pager" aria-label="Collection activity pages"><span><?= $activityTotal?$activityOffset+1:0 ?>–<?=min($activityOffset+10,$activityTotal)?> of <?=$activityTotal?> records</span><div><?php foreach(['Previous'=>$activityPage-1,'Next'=>$activityPage+1] as $label=>$target): ?><?php if($target<1||$target>$activityPages): ?><span class="pager-disabled"><?=h($label)?></span><?php else: ?><a class="button" href="?page=health&amp;activity_page=<?=$target?>#collection-activity"><?=h($label)?></a><?php endif; ?><?php endforeach; ?><span>Page <?=$activityPage?> of <?=$activityPages?></span></div></nav>
<div class="notice"><b>Measurement coverage</b><span>Collector failures are written to the PHP error log. CPU, memory, uptime history, and background job telemetry are not collected.</span></div></article></div>

